-- Chancellor (blind_map_battle_items) now shows the same "why it matters" write-up as Annalist and Herald once the
-- player has pinned a battle. The column set (description + _hu/_es/_fr/_de/_it) comes from the daily_battle_selection
-- migration. Applied once on 2026-10-19.
--
-- 1. 279 of the 293 map battles also exist in Annalist or Herald under the same name and year, so their write-up is copied
--    verbatim (Herald's first): one text serves them all, as the other two banks already do.
update public.blind_map_battle_items b
set description = s.description, description_hu = s.description_hu, description_es = s.description_es,
    description_fr = s.description_fr, description_de = s.description_de, description_it = s.description_it
from (
  select distinct on (k) k, description, description_hu, description_es, description_fr, description_de, description_it
  from (
    select regexp_replace(lower(c.battle), '[^a-z0-9]', '', 'g') || '_' || c.year as k, 1 as pri,
           c.description, c.description_hu, c.description_es, c.description_fr, c.description_de, c.description_it
    from public.casualties_multiplier_items c where c.description is not null
    union all
    select regexp_replace(lower(y.event), '[^a-z0-9]', '', 'g') || '_' || y.correct_year, 2,
           y.description, y.description_hu, y.description_es, y.description_fr, y.description_de, y.description_it
    from public.year_guess_items y where y.description is not null
  ) u
  order by k, pri
) s
where b.description is null
  and regexp_replace(lower(b.battle), '[^a-z0-9]', '', 'g') || '_' || b.year = s.k;

-- 2. The map's "Siege of Tenochtitlan" is Annalist's "Fall of Tenochtitlan" (same event, 1521).
update public.blind_map_battle_items b
set description = y.description, description_hu = y.description_hu, description_es = y.description_es,
    description_fr = y.description_fr, description_de = y.description_de, description_it = y.description_it
from public.year_guess_items y
where b.id = 'battlemap_244' and b.description is null and y.event = 'Fall of Tenochtitlan' and y.correct_year = 1521;

-- 3. Twelve battles that exist only on the map. Written from the Wikipedia article of each battle; kept to what it
--    supports. The 1858 "Battle of Monterrey (Reform War)" (battlemap_021) stays without one on purpose: its own
--    `source` says no such battle could be found, and Annalist and Herald leave it blank too.
update public.blind_map_battle_items b
set description = v.en, description_hu = v.hu, description_es = v.es, description_fr = v.fr, description_de = v.de, description_it = v.it
from (values
  ('battlemap_274',
   $d$In 525 BC the Persian king Cambyses II defeated the Egyptian pharaoh Psamtik III at Pelusium, the fortress guarding the eastern edge of the Nile Delta. The Egyptians fell back to Memphis, which was besieged and captured. The victory made Egypt a province of the Achaemenid Empire and began the Persian rule known as the 27th dynasty.$d$,
   $d$Kr. e. 525-ben II. Kambüszész perzsa király Péluszionnál, a Nílus-delta keleti szélét őrző erődnél legyőzte III. Pszammetikhosz egyiptomi fáraót. Az egyiptomiak Memphiszbe vonultak vissza, amelyet ostrom alá vettek és elfoglaltak. A győzelem Egyiptomot az Akhaimenida Birodalom tartományává tette, és megkezdődött a 27. dinasztiaként ismert perzsa uralom.$d$,
   $d$En el 525 a. C., el rey persa Cambises II derrotó al faraón egipcio Psamético III en Pelusio, la fortaleza que guardaba el extremo oriental del delta del Nilo. Los egipcios se replegaron a Menfis, que fue sitiada y tomada. La victoria convirtió a Egipto en una provincia del Imperio aqueménida e inició el dominio persa conocido como la dinastía XXVII.$d$,
   $d$En 525 av. J.-C., le roi perse Cambyse II vainquit le pharaon égyptien Psammétique III à Péluse, la forteresse qui gardait l'extrémité orientale du delta du Nil. Les Égyptiens se replièrent sur Memphis, qui fut assiégée et prise. La victoire fit de l'Égypte une province de l'Empire achéménide et inaugura la domination perse connue sous le nom de XXVIIe dynastie.$d$,
   $d$Im Jahr 525 v. Chr. besiegte der persische König Kambyses II. bei Pelusium, der Festung am östlichen Rand des Nildeltas, den ägyptischen Pharao Psammetich III. Die Ägypter zogen sich nach Memphis zurück, das belagert und eingenommen wurde. Der Sieg machte Ägypten zu einer Provinz des Achämenidenreichs und leitete die als 27. Dynastie bekannte Perserherrschaft ein.$d$,
   $d$Nel 525 a.C. il re persiano Cambise II sconfisse il faraone egizio Psammetico III a Pelusio, la fortezza che custodiva il margine orientale del delta del Nilo. Gli egizi si ritirarono a Menfi, che fu assediata e conquistata. La vittoria fece dell'Egitto una provincia dell'Impero achemenide e inaugurò il dominio persiano noto come XXVII dinastia.$d$),
  ('battlemap_275',
   $d$In 371 BC a Theban army under Epaminondas defeated the Spartans at Leuctra in Boeotia and killed their king, Cleombrotus I. Epaminondas massed his left wing fifty men deep to smash the strongest part of the Spartan line, and the larger Spartan army broke. The defeat ended Sparta's long military supremacy in Greece and opened a brief period of Theban dominance.$d$,
   $d$Kr. e. 371-ben az Epameinóndász vezette thébai sereg a boiótiai Leuktrainál legyőzte a spártaiakat, és megölte királyukat, I. Kleombrotoszt. Epameinóndász bal szárnyát ötven sor mélyre sűrítette, hogy szétzúzza a spártai arcvonal legerősebb részét, és a nagyobb létszámú spártai sereg megtört. A vereség véget vetett Spárta hosszú katonai fölényének Görögországban, és a thébai uralom rövid korszakát nyitotta meg.$d$,
   $d$En el 371 a. C., un ejército tebano al mando de Epaminondas derrotó a los espartanos en Leuctra, en Beocia, y mató a su rey, Cleómbroto I. Epaminondas concentró su ala izquierda en una formación de cincuenta hombres de fondo para destrozar la parte más fuerte de la línea espartana, y el ejército espartano, más numeroso, se quebró. La derrota puso fin a la larga supremacía militar de Esparta en Grecia y abrió un breve periodo de dominio tebano.$d$,
   $d$En 371 av. J.-C., une armée thébaine commandée par Épaminondas vainquit les Spartiates à Leuctres, en Béotie, et tua leur roi, Cléombrote Ier. Épaminondas massa son aile gauche sur cinquante rangs de profondeur pour fracasser la partie la plus forte de la ligne spartiate, et l'armée spartiate, plus nombreuse, céda. La défaite mit fin à la longue suprématie militaire de Sparte en Grèce et ouvrit une brève période d'hégémonie thébaine.$d$,
   $d$Im Jahr 371 v. Chr. besiegte ein thebanisches Heer unter Epameinondas die Spartaner bei Leuktra in Böotien und tötete ihren König Kleombrotos I. Epameinondas ließ seinen linken Flügel fünfzig Mann tief aufmarschieren, um den stärksten Teil der spartanischen Linie zu zerschmettern, und das zahlenmäßig überlegene spartanische Heer brach. Die Niederlage beendete Spartas lange militärische Vorherrschaft in Griechenland und eröffnete eine kurze Phase thebanischer Dominanz.$d$,
   $d$Nel 371 a.C. un esercito tebano al comando di Epaminonda sconfisse gli spartani a Leuttra, in Beozia, e uccise il loro re, Cleombroto I. Epaminonda ammassò la sua ala sinistra su cinquanta file di profondità per spezzare la parte più forte dello schieramento spartano, e il più numeroso esercito spartano cedette. La sconfitta pose fine alla lunga supremazia militare di Sparta in Grecia e aprì un breve periodo di dominio tebano.$d$),
  ('battlemap_276',
   $d$In 338 BC Philip II of Macedon defeated the combined armies of Athens, Thebes and their allies at Chaeronea in Boeotia. His eighteen-year-old son Alexander led the cavalry that helped break the Greek line, and Thebes' elite Sacred Band was wiped out. The victory made Macedon master of Greece, and the next year Philip organised the Greek states into the League of Corinth under his leadership.$d$,
   $d$Kr. e. 338-ban II. Philipposz makedón király a boiótiai Khairóneiánál legyőzte Athén, Théba és szövetségeseik egyesített seregét. Tizennyolc éves fia, Sándor vezette azt a lovasságot, amely segített áttörni a görög arcvonalat, és Théba elit alakulata, a Szent Sereg megsemmisült. A győzelem Makedóniát tette Görögország urává, és a következő évben Philipposz a görög államokat a saját vezetése alatt a Korinthoszi Szövetségbe szervezte.$d$,
   $d$En el 338 a. C., Filipo II de Macedonia derrotó en Queronea, en Beocia, a los ejércitos combinados de Atenas, Tebas y sus aliados. Su hijo Alejandro, de dieciocho años, dirigió la caballería que ayudó a romper la línea griega, y el Batallón Sagrado, la élite de Tebas, fue aniquilado. La victoria convirtió a Macedonia en dueña de Grecia, y al año siguiente Filipo organizó a los Estados griegos en la Liga de Corinto bajo su mando.$d$,
   $d$En 338 av. J.-C., Philippe II de Macédoine vainquit à Chéronée, en Béotie, les armées conjointes d'Athènes, de Thèbes et de leurs alliés. Son fils Alexandre, âgé de dix-huit ans, commanda la cavalerie qui contribua à rompre la ligne grecque, et le Bataillon sacré, l'élite de Thèbes, fut anéanti. La victoire fit de la Macédoine la maîtresse de la Grèce, et l'année suivante Philippe organisa les cités grecques en une ligue de Corinthe placée sous sa direction.$d$,
   $d$Im Jahr 338 v. Chr. besiegte Philipp II. von Makedonien bei Chaironeia in Böotien die vereinten Heere Athens, Thebens und ihrer Verbündeten. Sein achtzehnjähriger Sohn Alexander führte die Reiterei, die half, die griechische Linie zu durchbrechen, und Thebens Elitetruppe, die Heilige Schar, wurde aufgerieben. Der Sieg machte Makedonien zum Herrn Griechenlands, und im folgenden Jahr fasste Philipp die griechischen Staaten im Korinthischen Bund unter seiner Führung zusammen.$d$,
   $d$Nel 338 a.C. Filippo II di Macedonia sconfisse a Cheronea, in Beozia, gli eserciti congiunti di Atene, Tebe e dei loro alleati. Suo figlio Alessandro, diciottenne, guidò la cavalleria che contribuì a rompere lo schieramento greco, e il Battaglione Sacro, l'élite di Tebe, fu annientato. La vittoria rese la Macedonia padrona della Grecia, e l'anno seguente Filippo riunì gli Stati greci nella Lega di Corinto sotto la sua guida.$d$),
  ('battlemap_284',
   $d$In 168 BC a Roman army under Lucius Aemilius Paullus defeated King Perseus of Macedon at Pydna and ended the Third Macedonian War. The Macedonian phalanx lost its formation on broken ground and was cut down by the more flexible Roman legions. Perseus was captured, the Antigonid monarchy fell, and Macedon was split into four client republics, a major step in Rome's mastery of the Greek world.$d$,
   $d$Kr. e. 168-ban a Lucius Aemilius Paullus vezette római sereg Püdnánál legyőzte Perszeusz makedón királyt, és véget vetett a harmadik makedón háborúnak. A makedón falanx az egyenetlen terepen felbomlott, a rugalmasabb római légiók pedig lekaszabolták. Perszeuszt elfogták, az Antigonida-monarchia megbukott, Makedóniát pedig négy római függésben álló köztársaságra osztották, ami nagy lépés volt abban, hogy Róma uralma alá vonta a görög világot.$d$,
   $d$En el 168 a. C., un ejército romano al mando de Lucio Emilio Paulo derrotó en Pidna al rey Perseo de Macedonia y puso fin a la Tercera Guerra Macedónica. La falange macedonia perdió su formación en terreno irregular y fue destrozada por las legiones romanas, más flexibles. Perseo fue capturado, la monarquía antigónida cayó y Macedonia quedó dividida en cuatro repúblicas clientes, un paso decisivo en el dominio de Roma sobre el mundo griego.$d$,
   $d$En 168 av. J.-C., une armée romaine commandée par Paul Émile vainquit le roi Persée de Macédoine à Pydna et mit fin à la troisième guerre de Macédoine. La phalange macédonienne perdit sa formation sur un terrain accidenté et fut taillée en pièces par les légions romaines, plus souples. Persée fut capturé, la monarchie antigonide tomba et la Macédoine fut divisée en quatre républiques clientes, une étape majeure de la maîtrise de Rome sur le monde grec.$d$,
   $d$Im Jahr 168 v. Chr. besiegte ein römisches Heer unter Lucius Aemilius Paullus bei Pydna König Perseus von Makedonien und beendete den Dritten Makedonischen Krieg. Die makedonische Phalanx verlor auf unebenem Gelände ihre Ordnung und wurde von den beweglicheren römischen Legionen niedergemacht. Perseus geriet in Gefangenschaft, die Monarchie der Antigoniden fiel, und Makedonien wurde in vier abhängige Republiken geteilt, ein wichtiger Schritt auf Roms Weg zur Herrschaft über die griechische Welt.$d$,
   $d$Nel 168 a.C. un esercito romano al comando di Lucio Emilio Paolo sconfisse a Pidna il re Perseo di Macedonia e pose fine alla terza guerra macedonica. La falange macedone perse la propria formazione sul terreno accidentato e fu massacrata dalle più flessibili legioni romane. Perseo fu catturato, la monarchia antigonide cadde e la Macedonia fu divisa in quattro repubbliche clienti, un passo importante verso il dominio di Roma sul mondo greco.$d$),
  ('battlemap_286',
   $d$In 52 BC Julius Caesar besieged the Gallic leader Vercingetorix in the hilltop town of Alesia, in what is now Burgundy. Caesar walled in the town and then built a second line of fortifications facing outward, and this double ring held off a huge Gallic relief army while the defenders starved. Vercingetorix surrendered, ending the last great Gallic revolt and giving Rome control of Gaul.$d$,
   $d$Kr. e. 52-ben Julius Caesar ostrom alá vette a gall Vercingetorixet a mai Burgundia területén álló, dombtetői Alesia városában. Caesar körülzárta a települést, majd kifelé néző második védvonalat is épített, és ez a kettős gyűrű visszatartotta a gallok hatalmas felmentő seregét, miközben a védők éheztek. Vercingetorix megadta magát, ezzel véget ért az utolsó nagy gall felkelés, és Róma megszerezte Galliát.$d$,
   $d$En el 52 a. C., Julio César sitió al caudillo galo Vercingétorix en la ciudad de Alesia, situada en una colina de lo que hoy es Borgoña. César rodeó la ciudad con un muro y luego levantó una segunda línea de fortificaciones orientada hacia fuera; este doble cinturón detuvo a un enorme ejército galo de socorro mientras los sitiados pasaban hambre. Vercingétorix se rindió, lo que puso fin a la última gran revuelta gala y dio a Roma el control de la Galia.$d$,
   $d$En 52 av. J.-C., Jules César assiégea le chef gaulois Vercingétorix dans la ville fortifiée d'Alésia, perchée sur une colline de l'actuelle Bourgogne. César emmura la place, puis bâtit une seconde ligne de fortifications tournée vers l'extérieur ; ce double anneau arrêta une immense armée gauloise de secours pendant que les assiégés mouraient de faim. Vercingétorix se rendit, ce qui mit fin à la dernière grande révolte gauloise et donna à Rome le contrôle de la Gaule.$d$,
   $d$Im Jahr 52 v. Chr. belagerte Julius Cäsar den gallischen Anführer Vercingetorix in der Höhenstadt Alesia im heutigen Burgund. Cäsar schloss die Stadt mit einem Wall ein und errichtete dann eine zweite, nach außen gerichtete Befestigungslinie; dieser doppelte Ring hielt ein riesiges gallisches Entsatzheer auf, während die Eingeschlossenen hungerten. Vercingetorix ergab sich, womit der letzte große gallische Aufstand endete und Rom die Kontrolle über Gallien erlangte.$d$,
   $d$Nel 52 a.C. Giulio Cesare assediò il capo gallico Vercingetorige nella città di Alesia, arroccata su una collina dell'attuale Borgogna. Cesare circondò la città con una linea di fortificazioni e ne costruì poi una seconda rivolta verso l'esterno; questo doppio anello respinse un immenso esercito gallico di soccorso mentre gli assediati morivano di fame. Vercingetorige si arrese, ponendo fine all'ultima grande rivolta gallica e dando a Roma il controllo della Gallia.$d$),
  ('battlemap_288',
   $d$In 47 BC Julius Caesar crushed King Pharnaces II of Pontus at Zela in Anatolia, within days of arriving in the region. Pharnaces, a son of Mithridates the Great, had used the Roman civil war to win back his father's lands. Caesar's report of the victory to Rome is said to have read "Veni, vidi, vici": I came, I saw, I conquered.$d$,
   $d$Kr. e. 47-ben Julius Caesar a kisázsiai Zélánál szétzúzta II. Pharnakész pontoszi királyt, alig néhány nappal azután, hogy megérkezett a térségbe. Pharnakész, a Nagy Mithridatész fia, a római polgárháborút használta ki, hogy visszaszerezze apja földjeit. Caesar győzelemről szóló jelentése Rómának állítólag így szólt: „Veni, vidi, vici”, vagyis „jöttem, láttam, győztem”.$d$,
   $d$En el 47 a. C., Julio César aplastó en Zela, en Anatolia, al rey Farnaces II del Ponto, pocos días después de llegar a la región. Farnaces, hijo de Mitrídates el Grande, había aprovechado la guerra civil romana para recuperar las tierras de su padre. Se dice que el informe de César a Roma sobre la victoria decía «Veni, vidi, vici»: llegué, vi, vencí.$d$,
   $d$En 47 av. J.-C., Jules César écrasa à Zéla, en Anatolie, le roi Pharnace II du Pont, quelques jours après son arrivée dans la région. Pharnace, fils de Mithridate le Grand, avait profité de la guerre civile romaine pour reconquérir les terres de son père. Le rapport de César à Rome sur sa victoire aurait tenu en trois mots : « Veni, vidi, vici » — je suis venu, j'ai vu, j'ai vaincu.$d$,
   $d$Im Jahr 47 v. Chr. schlug Julius Cäsar bei Zela in Anatolien König Pharnakes II. von Pontos vernichtend, nur wenige Tage nach seiner Ankunft in der Region. Pharnakes, ein Sohn Mithridates' des Großen, hatte den römischen Bürgerkrieg genutzt, um die Länder seines Vaters zurückzugewinnen. Cäsars Siegesmeldung nach Rom soll gelautet haben: „Veni, vidi, vici“ – ich kam, sah und siegte.$d$,
   $d$Nel 47 a.C. Giulio Cesare sbaragliò a Zela, in Anatolia, il re Farnace II del Ponto, pochi giorni dopo il suo arrivo nella regione. Farnace, figlio di Mitridate il Grande, aveva approfittato della guerra civile romana per riconquistare le terre del padre. Si dice che il rapporto di Cesare a Roma sulla vittoria fosse: «Veni, vidi, vici», cioè venni, vidi, vinsi.$d$),
  ('battlemap_238',
   $d$In April 1483 a Castilian force under the Count of Cabra defeated a Granadan army at Lucena in Andalusia and captured Muhammad XII, the young emir of Granada, known to the Spanish as Boabdil. His capture let his father, Abu l-Hasan, retake the throne and deepened the feud inside the Nasrid dynasty, and Boabdil was freed only as a vassal of Castile. It was an early blow in the Granada War, which ended Muslim rule in Iberia in 1492.$d$,
   $d$1483 áprilisában a Cabra grófja vezette kasztíliai csapat az andalúziai Lucenánál legyőzte a granadai sereget, és elfogta XII. Mohamedet, Granada fiatal emírjét, akit a spanyolok Boabdilként ismertek. Fogsága lehetővé tette apjának, Abu l-Haszannak, hogy visszaszerezze a trónt, elmélyítette a Nászrida-dinasztián belüli viszályt, Boabdilt pedig csak Kasztília vazallusaként engedték szabadon. Ez korai csapás volt a Granadai háborúban, amely 1492-ben véget vetett az ibériai muszlim uralomnak.$d$,
   $d$En abril de 1483, una fuerza castellana al mando del conde de Cabra derrotó a un ejército granadino en Lucena, en Andalucía, y capturó a Muhammad XII, el joven emir de Granada, conocido por los españoles como Boabdil. Su captura permitió a su padre, Abu l-Hasan, recuperar el trono y ahondó la disputa dentro de la dinastía nazarí; Boabdil solo fue liberado como vasallo de Castilla. Fue un golpe temprano en la guerra de Granada, que puso fin al dominio musulmán en la península ibérica en 1492.$d$,
   $d$En avril 1483, une force castillane commandée par le comte de Cabra vainquit une armée grenadine à Lucena, en Andalousie, et captura Mohammed XII, le jeune émir de Grenade, que les Espagnols appelaient Boabdil. Sa capture permit à son père, Abu al-Hasan, de reprendre le trône et aggrava la querelle au sein de la dynastie nasride ; Boabdil ne fut libéré qu'en devenant vassal de la Castille. Ce fut un coup précoce dans la guerre de Grenade, qui mit fin en 1492 à la domination musulmane dans la péninsule Ibérique.$d$,
   $d$Im April 1483 besiegte ein kastilisches Heer unter dem Grafen von Cabra bei Lucena in Andalusien eine granadinische Armee und nahm Muhammad XII., den jungen Emir von Granada, gefangen, den die Spanier Boabdil nannten. Durch seine Gefangennahme konnte sein Vater Abu l-Hasan den Thron zurückgewinnen, und der Streit innerhalb der Nasridendynastie vertiefte sich; Boabdil kam nur als Vasall Kastiliens frei. Es war ein früher Schlag im Krieg um Granada, der 1492 die muslimische Herrschaft auf der Iberischen Halbinsel beendete.$d$,
   $d$Nell'aprile 1483 una forza castigliana al comando del conte di Cabra sconfisse un esercito granadino a Lucena, in Andalusia, e catturò Maometto XII, il giovane emiro di Granada, noto agli spagnoli come Boabdil. La sua cattura permise al padre, Abu l-Hasan, di riprendere il trono e approfondì la faida all'interno della dinastia nasride; Boabdil fu liberato solo come vassallo di Castiglia. Fu un colpo precoce nella guerra di Granada, che nel 1492 pose fine al dominio musulmano nella penisola iberica.$d$),
  ('battlemap_240',
   $d$In 1487 the Catholic Monarchs, Ferdinand and Isabella, besieged Málaga, the main seaport of the Nasrid kingdom of Granada, until its starving defenders surrendered in August after more than three months. Its fall cut Granada off from much of its trade and from help across the sea, and left the emirate much reduced. It was a key step toward the capture of Granada itself in 1492.$d$,
   $d$1487-ben a katolikus királyok, Ferdinánd és Izabella ostrom alá vették Málagát, a Nászrida Granadai Emírség fő tengeri kikötőjét, és védői három hónapnál is hosszabb ostrom után, augusztusban, kiéhezve megadták magukat. Eleste elvágta Granadát kereskedelmének nagy részétől és a tengeren túli segítségtől, az emírséget pedig jelentősen megcsökkentette. Kulcslépés volt Granada 1492-es elfoglalása felé.$d$,
   $d$En 1487, los Reyes Católicos, Fernando e Isabel, sitiaron Málaga, el principal puerto marítimo del reino nazarí de Granada, hasta que sus defensores, hambrientos, se rindieron en agosto tras más de tres meses. Su caída aisló a Granada de gran parte de su comercio y de la ayuda por mar, y dejó al emirato muy reducido. Fue un paso clave hacia la toma de la propia Granada en 1492.$d$,
   $d$En 1487, les Rois catholiques, Ferdinand et Isabelle, assiégèrent Malaga, le principal port maritime du royaume nasride de Grenade, jusqu'à ce que ses défenseurs affamés se rendent en août, après plus de trois mois. Sa chute coupa Grenade d'une grande partie de son commerce et de l'aide venue par la mer, et laissa l'émirat très affaibli. Ce fut une étape clé vers la prise de Grenade elle-même en 1492.$d$,
   $d$Im Jahr 1487 belagerten die Katholischen Könige Ferdinand und Isabella Málaga, den wichtigsten Seehafen des nasridischen Königreichs Granada, bis seine ausgehungerten Verteidiger im August nach mehr als drei Monaten kapitulierten. Der Fall der Stadt schnitt Granada von einem Großteil seines Handels und von Hilfe über das Meer ab und ließ das Emirat stark geschwächt zurück. Er war ein wichtiger Schritt zur Eroberung Granadas selbst im Jahr 1492.$d$,
   $d$Nel 1487 i Re Cattolici, Ferdinando e Isabella, assediarono Malaga, il principale porto marittimo del regno nasride di Granada, finché i suoi difensori, stremati dalla fame, si arresero in agosto dopo più di tre mesi. La sua caduta tagliò Granada fuori da gran parte dei suoi commerci e dagli aiuti via mare, e lasciò l'emirato molto ridimensionato. Fu un passo decisivo verso la conquista della stessa Granada nel 1492.$d$),
  ('battlemap_250',
   $d$In September 1542 royal forces under Cristóbal Vaca de Castro, the governor sent by the Spanish Crown, defeated the followers of Diego de Almagro the Younger at Chupas in the Peruvian Andes. Almagro's supporters had killed Francisco Pizarro the year before, and Almagro himself was captured and executed after the battle. It ended the first round of civil war among the conquistadors of Peru, but the Crown's New Laws soon provoked a new rebellion under Gonzalo Pizarro.$d$,
   $d$1542 szeptemberében a Cristóbal Vaca de Castro, a spanyol korona által küldött kormányzó vezette királyi csapatok a perui Andokban fekvő Chupasnál legyőzték ifjabb Diego de Almagro híveit. Almagro támogatói egy évvel korábban megölték Francisco Pizarrót, magát Almagrót pedig a csata után elfogták és kivégezték. A csata lezárta a perui konkvisztádorok közötti polgárháború első szakaszát, de a korona Új törvényei hamarosan új lázadást váltottak ki Gonzalo Pizarro vezetésével.$d$,
   $d$En septiembre de 1542, las fuerzas reales al mando de Cristóbal Vaca de Castro, el gobernador enviado por la Corona española, derrotaron en Chupas, en los Andes peruanos, a los seguidores de Diego de Almagro el Mozo. Los partidarios de Almagro habían matado a Francisco Pizarro el año anterior, y el propio Almagro fue capturado y ejecutado tras la batalla. Puso fin a la primera ronda de guerras civiles entre los conquistadores del Perú, pero las Leyes Nuevas de la Corona provocaron pronto una nueva rebelión encabezada por Gonzalo Pizarro.$d$,
   $d$En septembre 1542, les forces royales de Cristóbal Vaca de Castro, le gouverneur envoyé par la Couronne espagnole, vainquirent à Chupas, dans les Andes péruviennes, les partisans de Diego de Almagro le Jeune. Les partisans d'Almagro avaient tué Francisco Pizarro l'année précédente, et Almagro lui-même fut capturé et exécuté après la bataille. La bataille mit fin à la première phase de la guerre civile entre les conquistadors du Pérou, mais les Nouvelles Lois de la Couronne provoquèrent bientôt une nouvelle rébellion menée par Gonzalo Pizarro.$d$,
   $d$Im September 1542 besiegten königliche Truppen unter Cristóbal Vaca de Castro, dem von der spanischen Krone entsandten Gouverneur, bei Chupas in den peruanischen Anden die Anhänger Diego de Almagros des Jüngeren. Almagros Anhänger hatten im Jahr zuvor Francisco Pizarro getötet, und Almagro selbst wurde nach der Schlacht gefangen genommen und hingerichtet. Sie beendete die erste Runde des Bürgerkriegs unter den Konquistadoren Perus, doch die Neuen Gesetze der Krone lösten bald einen neuen Aufstand unter Gonzalo Pizarro aus.$d$,
   $d$Nel settembre 1542 le forze regie di Cristóbal Vaca de Castro, il governatore inviato dalla Corona spagnola, sconfissero a Chupas, sulle Ande peruviane, i seguaci di Diego de Almagro il Giovane. I sostenitori di Almagro avevano ucciso Francisco Pizarro l'anno prima, e lo stesso Almagro fu catturato e giustiziato dopo la battaglia. Chiuse il primo ciclo di guerre civili tra i conquistadores del Perù, ma le Nuove Leggi della Corona provocarono presto una nuova ribellione guidata da Gonzalo Pizarro.$d$),
  ('battlemap_251',
   $d$On 24 April 1547 Emperor Charles V's army caught the forces of the Protestant Schmalkaldic League withdrawing along the Elbe at Mühlberg in Saxony and routed them, capturing Elector John Frederick I of Saxony. The victory gave Charles control of much of Germany and passed John Frederick's electoral title to his cousin Maurice, a fellow Protestant who had sided with the emperor. It did not end the Reformation: Maurice turned against Charles in 1552, and the Peace of Augsburg of 1555 let each ruler choose Lutheranism or Catholicism for their lands.$d$,
   $d$1547. április 24-én V. Károly császár serege a szászországi Mühlbergnél az Elba mentén visszavonuló protestáns Schmalkaldeni Szövetség erőire csapott, szétverte őket, és elfogta I. János Frigyes szász választófejedelmet. A győzelem Károlynak Németország nagy része fölött adott hatalmat, János Frigyes választófejedelmi címét pedig unokatestvére, Móric kapta, aki szintén protestáns volt, de a császár oldalára állt. A reformációt ez nem szüntette meg: Móric 1552-ben Károly ellen fordult, és az 1555-ös augsburgi vallásbéke lehetővé tette, hogy minden uralkodó maga válassza meg földjén az evangélikus vagy a katolikus hitet.$d$,
   $d$El 24 de abril de 1547, el ejército del emperador Carlos V alcanzó en Mühlberg, en Sajonia, a las fuerzas protestantes de la Liga de Esmalcalda cuando se retiraban a lo largo del Elba y las puso en fuga, capturando al elector Juan Federico I de Sajonia. La victoria dio a Carlos el control de gran parte de Alemania y transfirió el título electoral de Juan Federico a su primo Mauricio, también protestante, que se había puesto del lado del emperador. No acabó con la Reforma: Mauricio se volvió contra Carlos en 1552, y la Paz de Augsburgo de 1555 dejó que cada príncipe eligiera el luteranismo o el catolicismo para sus tierras.$d$,
   $d$Le 24 avril 1547, l'armée de l'empereur Charles Quint rattrapa à Mühlberg, en Saxe, les forces protestantes de la ligue de Smalkalde qui se retiraient le long de l'Elbe et les mit en déroute, capturant l'électeur Jean-Frédéric Ier de Saxe. La victoire donna à Charles le contrôle d'une grande partie de l'Allemagne et transmit le titre d'électeur de Jean-Frédéric à son cousin Maurice, protestant lui aussi, qui s'était rangé du côté de l'empereur. Elle ne mit pas fin à la Réforme : Maurice se retourna contre Charles en 1552, et la paix d'Augsbourg de 1555 laissa à chaque prince le choix du luthéranisme ou du catholicisme pour ses terres.$d$,
   $d$Am 24. April 1547 holte das Heer Kaiser Karls V. bei Mühlberg in Sachsen die sich an der Elbe zurückziehenden Truppen des protestantischen Schmalkaldischen Bundes ein und schlug sie vernichtend; Kurfürst Johann Friedrich I. von Sachsen geriet in Gefangenschaft. Der Sieg gab Karl die Kontrolle über große Teile Deutschlands und übertrug Johann Friedrichs Kurwürde auf seinen Vetter Moritz, einen Glaubensgenossen, der sich auf die Seite des Kaisers geschlagen hatte. Die Reformation beendete er nicht: Moritz wandte sich 1552 gegen Karl, und der Augsburger Religionsfriede von 1555 ließ jedem Landesherrn die Wahl zwischen Luthertum und Katholizismus für sein Land.$d$,
   $d$Il 24 aprile 1547 l'esercito dell'imperatore Carlo V raggiunse a Mühlberg, in Sassonia, le forze protestanti della Lega di Smalcalda che si ritiravano lungo l'Elba e le mise in rotta, catturando l'elettore Giovanni Federico I di Sassonia. La vittoria diede a Carlo il controllo di gran parte della Germania e trasferì il titolo elettorale di Giovanni Federico al cugino Maurizio, anch'egli protestante, che si era schierato con l'imperatore. Non pose fine alla Riforma: Maurizio si rivoltò contro Carlo nel 1552, e la pace di Augusta del 1555 lasciò a ogni principe la scelta tra luteranesimo e cattolicesimo per i propri territori.$d$),
  ('battlemap_253',
   $d$In 1552 roughly two thousand defenders under István Dobó held the castle of Eger in northern Hungary against a far larger Ottoman army, and after about five weeks the Ottomans withdrew. Soldiers, townspeople and women all took part in the defence, which Hungarians remember as a victory against hopeless odds. The Ottomans had by then taken Buda and much of central Hungary, but Eger stayed out of their hands for another 44 years.$d$,
   $d$1552-ben nagyjából kétezer védő Dobó István vezetésével megtartotta az észak-magyarországi egri várat egy sokkal nagyobb oszmán sereggel szemben, és mintegy öt hét után az oszmánok visszavonultak. A védelemben katonák, városlakók és asszonyok egyaránt részt vettek, a magyarok pedig reménytelen esélyek elleni győzelemként emlékeznek rá. Az oszmánok addigra elfoglalták Budát és Magyarország középső részének nagy részét, de Eger még negyvennégy évig kívül maradt a kezükön.$d$,
   $d$En 1552, unos dos mil defensores al mando de István Dobó resistieron en el castillo de Eger, en el norte de Hungría, frente a un ejército otomano mucho mayor, y tras unas cinco semanas los otomanos se retiraron. Soldados, vecinos y mujeres participaron en la defensa, que los húngaros recuerdan como una victoria contra todo pronóstico. Para entonces los otomanos habían tomado Buda y buena parte del centro de Hungría, pero Eger se mantuvo fuera de su control durante otros 44 años.$d$,
   $d$En 1552, environ deux mille défenseurs sous les ordres d'István Dobó tinrent le château d'Eger, dans le nord de la Hongrie, face à une armée ottomane bien plus nombreuse, et après environ cinq semaines les Ottomans se retirèrent. Soldats, habitants et femmes participèrent tous à la défense, que les Hongrois gardent en mémoire comme une victoire contre toute attente. Les Ottomans avaient alors pris Buda et une grande partie du centre de la Hongrie, mais Eger resta hors de leur portée pendant encore 44 ans.$d$,
   $d$Im Jahr 1552 hielten etwa zweitausend Verteidiger unter István Dobó die Burg Eger in Nordungarn gegen ein weit größeres osmanisches Heer, und nach etwa fünf Wochen zogen die Osmanen ab. Soldaten, Bürger und Frauen beteiligten sich an der Verteidigung, an die sich die Ungarn als Sieg gegen aussichtslose Übermacht erinnern. Die Osmanen hatten damals bereits Buda und große Teile Zentralungarns erobert, doch Eger blieb noch weitere 44 Jahre außerhalb ihrer Hand.$d$,
   $d$Nel 1552 circa duemila difensori al comando di István Dobó tennero il castello di Eger, nell'Ungheria settentrionale, contro un esercito ottomano molto più numeroso, e dopo circa cinque settimane gli ottomani si ritirarono. Soldati, cittadini e donne presero tutti parte alla difesa, che gli ungheresi ricordano come una vittoria contro ogni pronostico. Gli ottomani avevano ormai preso Buda e gran parte dell'Ungheria centrale, ma Eger rimase fuori dalla loro portata per altri 44 anni.$d$),
  ('battlemap_263',
   $d$On 4 July 1610 a Polish-Lithuanian army under Hetman Stanisław Żółkiewski routed a much larger Russian and Swedish force at Klushino, west of Moscow, with a charge of the winged hussars. Tsar Vasily Shuisky was overthrown soon afterwards, and Polish troops entered Moscow and held it from 1610 to 1612, during Russia's Time of Troubles. They were driven out only when a Russian national army under Minin and Pozharsky retook the city.$d$,
   $d$1610. július 4-én a Stanisław Żółkiewski hetman vezette lengyel–litván sereg a Moszkvától nyugatra fekvő Klusinónál szárnyas huszárok rohamával szétverte a jóval nagyobb orosz–svéd haderőt. Vaszilij Sujszkij cárt nem sokkal később megbuktatták, a lengyel csapatok pedig bevonultak Moszkvába, és 1610 és 1612 között, az orosz Zűrzavaros idők során megszállva tartották. Csak akkor űzték ki őket, amikor a Minyin és Pozsarszkij vezette orosz nemzeti hadsereg visszafoglalta a várost.$d$,
   $d$El 4 de julio de 1610, un ejército polaco-lituano al mando del hetmán Stanisław Żółkiewski derrotó en Klúshino, al oeste de Moscú, a una fuerza rusa y sueca mucho mayor mediante una carga de húsares alados. El zar Basilio Shuiski fue derrocado poco después, y las tropas polacas entraron en Moscú y la ocuparon de 1610 a 1612, durante el Tiempo de Dificultades de Rusia. Solo fueron expulsadas cuando un ejército nacional ruso al mando de Minin y Pozharski recuperó la ciudad.$d$,
   $d$Le 4 juillet 1610, une armée polono-lituanienne commandée par l'hetman Stanisław Żółkiewski mit en déroute à Klouchino, à l'ouest de Moscou, une force russo-suédoise bien plus nombreuse, par une charge des hussards ailés. Le tsar Basile Chouïski fut renversé peu après, et les troupes polonaises entrèrent à Moscou et l'occupèrent de 1610 à 1612, pendant le Temps des troubles de la Russie. Elles n'en furent chassées que lorsqu'une armée nationale russe sous Minine et Pojarski reprit la ville.$d$,
   $d$Am 4. Juli 1610 schlug ein polnisch-litauisches Heer unter Hetman Stanisław Żółkiewski bei Kluschino westlich von Moskau mit dem Angriff der geflügelten Husaren eine weit größere russisch-schwedische Streitmacht. Zar Wassili Schuiski wurde bald darauf gestürzt, und polnische Truppen zogen in Moskau ein und hielten es von 1610 bis 1612, in Russlands Zeit der Wirren. Vertrieben wurden sie erst, als ein russisches Nationalheer unter Minin und Poscharski die Stadt zurückeroberte.$d$,
   $d$Il 4 luglio 1610 un esercito polacco-lituano al comando dell'hetman Stanisław Żółkiewski mise in rotta a Klušino, a ovest di Mosca, una forza russo-svedese molto più numerosa, con una carica degli ussari alati. Lo zar Vasilij Šujskij fu deposto poco dopo, e le truppe polacche entrarono a Mosca e la tennero dal 1610 al 1612, durante il Periodo dei torbidi della Russia. Furono scacciate solo quando un esercito nazionale russo al comando di Minin e Požarskij riconquistò la città.$d$)
